import{_ as t,o as h,c as i,a2 as r}from"./chunks/framework.BBd5PKnH.js";const o="/dev-notes/assets/sect2-two-teams.CCJYGoEF.svg",a="/dev-notes/assets/sect1-day-night.DedYOvI9.svg",c="/dev-notes/assets/sect3-morning-evening.BuJavG44.svg",v=JSON.parse('{"title":"Sect: phe ngày và phe đêm","description":"","frontmatter":{},"headers":[],"relativePath":"astro/sect/sect-note/sect-diurnal-nocturnal.md","filePath":"astro/sect/sect-note/sect-diurnal-nocturnal.md"}'),g={name:"astro/sect/sect-note/sect-diurnal-nocturnal.md"};function s(e,n,l,u,m,d){return h(),i("div",null,[...n[0]||(n[0]=[r('<h1 id="sect-phe-ngay-va-phe-đem" tabindex="-1">Sect: phe ngày và phe đêm <a class="header-anchor" href="#sect-phe-ngay-va-phe-đem" aria-label="Permalink to &quot;Sect: phe ngày và phe đêm&quot;">​</a></h1><p><em>(Demetra George, Ancient Astrology in Theory and Practice Vol. I: &quot;The Third Classification of Planets is According to Sect&quot;, &quot;Diurnal and Nocturnal Sect&quot;, Figure 9, Example Charts; kèm đoạn trích Paulus)</em></p><p>Quy ước: <strong>[Sách]</strong> = nội dung có trong trang sách. <strong>[Bổ sung]</strong> = mình tự diễn giải hoặc ghép từ các note trước. Phần [Bổ sung] không phải lời tác giả.</p><hr><h2 id="_0-tom-tat-nhanh" tabindex="-1">0. Tóm tắt nhanh <a class="header-anchor" href="#_0-tom-tat-nhanh" aria-label="Permalink to &quot;0. Tóm tắt nhanh&quot;">​</a></h2><ul><li><strong>Sect</strong> = &quot;phe/đội&quot;. Mỗi lá số thuộc một phe: <strong>ngày (diurnal)</strong> nếu Sun ở trên đường chân trời, <strong>đêm (nocturnal)</strong> nếu Sun ở dưới.</li><li>Mỗi hành tinh cũng thuộc một phe. <strong>Đội Sun</strong>: Sun, Jupiter, Saturn. <strong>Đội Moon</strong>: Moon, Venus, Mars. <strong>Mercury</strong> là common (theo phase).</li><li>Hành tinh <strong>cùng phe</strong> với lá số có nhiều &quot;quyền hạn và tự do&quot; hơn để mang ra ý nghĩa tích cực. Hành tinh <strong>nghịch phe</strong> thì khó hơn.</li><li>Sect là <strong>một trong những điều đầu tiên</strong> cần xem khi phân tích condition của hành tinh, và là điểm xuất phát của nhiều kỹ thuật khác (tuổi thọ, mức độ nổi bật, công thức Part of Fortune...).</li></ul><hr><h2 id="_1-đoan-trich-paulus" tabindex="-1">1. Đoạn trích Paulus <a class="header-anchor" href="#_1-đoan-trich-paulus" aria-label="Permalink to &quot;1. Đoạn trích Paulus&quot;">​</a></h2><p><strong>[Sách] Bản dịch ý</strong></p><blockquote><p>Vì toàn thể được Mặt Trời và Mặt Trăng cai quản, và không có gì trong vũ trụ ra đời mà thiếu sự cai quản của hai tinh tú này, nên cần giải thích sect của Mặt Trời và Mặt Trăng: mỗi bên được phân cho điều gì, và mọi thứ hội tụ lại qua hai bên như thế nào.</p><ul><li><strong>Mặt Trời</strong> được phân cho <strong>ban ngày</strong>, <strong>sự mọc buổi sáng</strong> (morning rising) và <strong>các cung nam</strong>. Đội thị vệ cầm giáo của nó là <strong>Saturn và Jupiter</strong>.</li><li><strong>Mặt Trăng</strong> được phân cho <strong>ban đêm</strong>, <strong>sự mọc buổi chiều</strong> (evening rising) và <strong>các cung nữ</strong>. Thị vệ cầm giáo của nó là <strong>Mars và Venus</strong>.</li><li><strong>Mercury</strong> được coi là mang bản chất <strong>chung</strong> (common). Khi mọc buổi sáng, nó &quot;hoan hỷ&quot; (rejoice) cùng Mặt Trời. Khi mọc buổi chiều, nó hoan hỷ cùng Mặt Trăng.</li></ul><p>— Paulus</p></blockquote><p><strong>Giải thích:</strong></p><ul><li>Paulus gom mỗi bên thành một <strong>bộ ba</strong>: <em>ngày + morning + cung nam</em> (đội Sun) và <em>đêm + evening + cung nữ</em> (đội Moon).</li><li>&quot;Thị vệ cầm giáo&quot; nghĩa là các hành tinh còn lại làm đội hộ vệ cho hai luminary (Sun, Moon).</li><li>Đây là cơ sở của quy ước <strong>morning = phe ngày, evening = phe đêm</strong>.</li><li><strong>[Bổ sung]</strong> Bộ ba này trùng với hai điều kiện đầu của Chương 5 (giới tính của cung và solar phase). Vì thế một hành tinh có thể bị lệch ở điều kiện này nhưng không lệch ở điều kiện kia.</li></ul><h3 id="hinh-2-hai-đoi-cua-paulus" tabindex="-1">Hình 2: Hai &quot;đội&quot; của Paulus <a class="header-anchor" href="#hinh-2-hai-đoi-cua-paulus" aria-label="Permalink to &quot;Hình 2: Hai &quot;đội&quot; của Paulus&quot;">​</a></h3><p><img src="'+o+'" alt="Hai đội"></p><hr><h2 id="_2-phan-loai-thu-ba-theo-sect" tabindex="-1">2. Phân loại thứ ba: theo sect <a class="header-anchor" href="#_2-phan-loai-thu-ba-theo-sect" aria-label="Permalink to &quot;2. Phân loại thứ ba: theo sect&quot;">​</a></h2><p><strong>[Sách] Bản dịch ý</strong></p><ul><li><em>Sect</em> bắt nguồn từ tiếng Hy Lạp <strong>hairesis</strong>, nghĩa là phe phái, liên minh, trường phái tư tưởng, thậm chí đảng chính trị hay đội.</li><li>Nhiều học thuyết chiêm tinh cổ dựa trên tập quán xã hội của thế giới cổ đại. Sect phản ánh hệ thống <strong>đồng minh và kẻ thù</strong>, việc xác định bạn thù dựa trên liên minh, và <strong>cán cân quyền lực</strong>: phe nào đang giữ đặc quyền và thống trị.</li><li>Sect của lá số và tình trạng sect của một hành tinh là <strong>một trong những cân nhắc đầu tiên</strong> khi phân tích condition của hành tinh.</li></ul><hr><h2 id="_3-sect-ngay-va-sect-đem" tabindex="-1">3. Sect ngày và sect đêm <a class="header-anchor" href="#_3-sect-ngay-va-sect-đem" aria-label="Permalink to &quot;3. Sect ngày và sect đêm&quot;">​</a></h2><p><strong>[Sách] Bản dịch ý</strong></p><ul><li>Chiêm tinh cổ có hai sect: <strong>diurnal</strong> (ngày) và <strong>nocturnal</strong> (đêm). Sinh ban ngày thì lá số là diurnal, sinh ban đêm thì nocturnal.</li><li><strong>Sect của một hành tinh</strong> quyết định nó có bao nhiêu <strong>quyền hạn và tự do</strong> để mang ra ý nghĩa tích cực cho đương số. Sect cũng cho biết hành tinh đó <strong>nên dựa vào hành tinh nào</strong> để hỗ trợ cho mục tiêu của mình.</li><li>Việc đánh giá hành tinh tốt hay xấu theo sect là đặc điểm chính của chiêm tinh cổ, và phần lớn đã mất trong chiêm tinh hiện đại.</li><li>Sect của lá số còn là <strong>điểm xuất phát</strong> của nhiều kỹ thuật: tính tuổi thọ, đánh giá mức độ nổi bật của đời người, <strong>công thức của nhiều lot</strong> (Arabic Parts), và chọn hành tinh đại diện cho các chủ đề như cha mẹ.</li><li><strong>Figure 9:</strong> lá số ngày thì Sun ở trên trục ASC–DSC, lá số đêm thì Sun ở dưới trục ASC–DSC.</li></ul><hr><h2 id="_4-cach-xac-đinh-ngay-đem" tabindex="-1">4. Cách xác định ngày/đêm <a class="header-anchor" href="#_4-cach-xac-đinh-ngay-đem" aria-label="Permalink to &quot;4. Cách xác định ngày/đêm&quot;">​</a></h2><p><strong>[Sách] Bản dịch ý</strong></p><ul><li>Trục cần nhìn là <strong>trục ASC–DSC theo độ chính xác</strong>, đi qua nhà 1 và nhà 7. Đó <strong>không phải</strong> đường ngang ở đầu nhà 1 như trong các hệ quadrant (Placidus...).</li><li>Trục này đánh dấu <strong>đường chân trời</strong> (nơi trời gặp đất). Sách nói hầu hết bản in từ máy tính theo whole sign <strong>không vẽ nó chính xác về mặt hình ảnh</strong>.</li><li>Sun <strong>trên</strong> đường chân trời thì là lá số ngày. Sun <strong>dưới</strong> đường chân trời thì là lá số đêm. Có thể kiểm tra bằng giờ sinh (ban ngày hay ban đêm).</li></ul><p><strong>[Bổ sung]</strong> &quot;Ngày/đêm&quot; ở đây nghĩa là Sun ở trên hay dưới đường chân trời, không phải số giờ trên đồng hồ. Nếu sinh sát lúc mặt trời mọc hoặc lặn, hoặc vào mùa có ngày rất dài/ngắn, nên kiểm theo độ của Sun và trục ASC/DSC.</p><h3 id="hinh-1-ngay-đem-tren-hai-la-so-that" tabindex="-1">Hình 1: Ngày/đêm trên hai lá số thật <a class="header-anchor" href="#hinh-1-ngay-đem-tren-hai-la-so-that" aria-label="Permalink to &quot;Hình 1: Ngày/đêm trên hai lá số thật&quot;">​</a></h3><p><img src="'+a+'" alt="Ngày và đêm"></p><ul><li>Đường đỏ dày = chân trời (ASC–DSC theo độ thật). Nửa vàng = trên chân trời, nửa xanh xám = dưới chân trời.</li><li>Viền xanh = cùng sect với lá số, viền đỏ = nghịch sect, viền xám = Mercury.</li><li>Chân trời cắt ngang giữa nhà 1 và nhà 7 chứ không nằm ở ranh giới nhà.</li></ul><hr><h2 id="_5-hai-la-so-vi-du" tabindex="-1">5. Hai lá số ví dụ <a class="header-anchor" href="#_5-hai-la-so-vi-du" aria-label="Permalink to &quot;5. Hai lá số ví dụ&quot;">​</a></h2><p><strong>[Sách]</strong></p><ul><li><strong>Chart I (Kennedy) là diurnal.</strong> Trục ASC/DSC đi từ 17°58&#39; Scorpio đến 17°58&#39; Taurus. Sun ở 5° Leo <strong>trên</strong> chân trời. Giờ sinh 2:30 pm.</li><li><strong>Chart II (Picasso) là nocturnal.</strong> Trục đi từ 5°38&#39; Leo đến 5°38&#39; Aquarius, Sun ở 2° Scorpio <strong>dưới</strong> chân trời. Giờ sinh 11:15 pm.</li></ul><p><strong>[Bổ sung] Sect status của từng hành tinh</strong></p><table tabindex="0"><thead><tr><th></th><th>Cùng sect (in sect)</th><th>Nghịch sect (out of sect)</th><th>Common</th></tr></thead><tbody><tr><td><strong>Kennedy (ngày)</strong></td><td>Sun, Jupiter, Saturn</td><td>Moon, Venus, Mars</td><td>Mercury</td></tr><tr><td><strong>Picasso (đêm)</strong></td><td>Moon, Venus, Mars</td><td>Sun, Jupiter, Saturn</td><td>Mercury</td></tr></tbody></table><hr><h2 id="_6-morning-rising-va-evening-rising" tabindex="-1">6. Morning rising và evening rising <a class="header-anchor" href="#_6-morning-rising-va-evening-rising" aria-label="Permalink to &quot;6. Morning rising và evening rising&quot;">​</a></h2><p>Hình dưới minh họa lại ý của Paulus bằng một ngày trên bầu trời.</p><p><img src="'+c+'" alt="Morning và evening"></p><ul><li><strong>Morning</strong>: hành tinh có kinh độ <strong>nhỏ hơn</strong> Sun (tối đa 180°). Nó mọc <strong>trước</strong> Sun nên thấy lúc rạng đông (như &quot;sao Mai&quot;). Thuộc đội Sun, <strong>nam hóa</strong>.</li><li><strong>Evening</strong>: hành tinh có kinh độ <strong>lớn hơn</strong> Sun. Nó mọc <strong>sau</strong> Sun nên thấy lúc hoàng hôn (như &quot;sao Hôm&quot;). Thuộc đội Moon, <strong>nữ hóa</strong>.</li><li>Hình chỉ là sơ đồ minh họa, không phải giờ mọc thật của hành tinh nào.</li></ul><hr><h2 id="_7-lien-he-voi-hai-la-so-đa-phan-tich" tabindex="-1">7. Liên hệ với hai lá số đã phân tích <a class="header-anchor" href="#_7-lien-he-voi-hai-la-so-đa-phan-tich" aria-label="Permalink to &quot;7. Liên hệ với hai lá số đã phân tích&quot;">​</a></h2><ol><li><strong>Hình vẽ whole sign của mình đúng ý sách:</strong> đường ASC nằm bên trong nhà 1 và hơi nghiêng, chính là đường chân trời theo độ.</li><li><strong>Part of Fortune</strong> mình tính theo sect khớp sách: Kennedy (ngày) dùng Asc + Moon − Sun, Picasso (đêm) dùng Asc + Sun − Moon.</li><li><strong>Mercury (common)</strong> theo Paulus: <ul><li>Kennedy: Mercury ở morning phase trong lá số ngày, nên &quot;hoan hỷ cùng Sun&quot;.</li><li>Picasso: Mercury ở evening phase trong lá số đêm, nên &quot;hoan hỷ cùng Moon&quot;.</li><li>[Bổ sung] Cách áp dụng này là của mình.</li></ul></li><li><strong>[Bổ sung] Phase và sect có thể không cùng chiều.</strong> Ví dụ Moon của Kennedy ở morning phase (thuộc đội Sun) nhưng trong lá số ngày thì Moon nghịch sect. Mình chưa tìm thấy sách nói gì về trường hợp này, nên chỉ ghi nhận như một nhận xét.</li></ol><hr><h2 id="_8-tu-vung" tabindex="-1">8. Từ vựng <a class="header-anchor" href="#_8-tu-vung" aria-label="Permalink to &quot;8. Từ vựng&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Anh</th><th>Việt gợi ý</th></tr></thead><tbody><tr><td>Sect</td><td>Phe, đội (từ Hy Lạp <em>hairesis</em>)</td></tr><tr><td>Diurnal / Nocturnal</td><td>Ngày / Đêm</td></tr><tr><td>In sect / Out of sect</td><td>Cùng sect / Nghịch sect</td></tr><tr><td>Horizon</td><td>Đường chân trời (trục ASC–DSC)</td></tr><tr><td>Spear-bearing guards</td><td>Thị vệ cầm giáo</td></tr><tr><td>Common</td><td>Chung (không thuộc hẳn phe nào)</td></tr><tr><td>Morning rising / Evening rising</td><td>Mọc buổi sáng / Mọc buổi chiều</td></tr><tr><td>Rejoice</td><td>Hoan hỷ (vui vẻ, hợp phe)</td></tr><tr><td>Lot (Arabic Part)</td><td>Điểm Lot (Part of Fortune...)</td></tr></tbody></table><hr><h2 id="_9-tu-kiem-tra" tabindex="-1">9. Tự kiểm tra <a class="header-anchor" href="#_9-tu-kiem-tra" aria-label="Permalink to &quot;9. Tự kiểm tra&quot;">​</a></h2><ol><li>Lá số ngày hay đêm được xác định bằng gì? Có phải bằng đồng hồ không?</li><li>Hành tinh nào thuộc đội Sun, đội Moon? Mercury thì sao?</li><li>Vì sao sách dặn dùng trục ASC–DSC theo độ thật, không dùng đường ngang đầu nhà 1?</li><li>Trong lá số ngày, Mars có cùng sect không?</li></ol><details><summary>Đáp án gợi ý</summary><ol><li>Bằng việc Sun ở trên hay dưới đường chân trời (trục ASC–DSC theo độ). Giờ sinh chỉ để kiểm tra lại.</li><li>Đội Sun: Sun, Jupiter, Saturn. Đội Moon: Moon, Venus, Mars. Mercury là common, theo phase (morning theo Sun, evening theo Moon).</li><li>Vì đường chân trời thật đi qua giữa nhà 1 và nhà 7 theo độ chính xác của Asc/Dsc, còn đường ngang đầu nhà 1 chỉ là cách vẽ của các hệ quadrant.</li><li>Không. Mars thuộc đội Moon nên trong lá số ngày nó nghịch sect (như trong lá số Kennedy).</li></ol></details><hr><h2 id="_10-nhung-điem-nen-kiem-tra-lai" tabindex="-1">10. Những điểm nên kiểm tra lại <a class="header-anchor" href="#_10-nhung-điem-nen-kiem-tra-lai" aria-label="Permalink to &quot;10. Những điểm nên kiểm tra lại&quot;">​</a></h2><ul><li><strong>[Bổ sung]</strong> Việc gắn Mercury &quot;hoan hỷ&quot; với phase của Kennedy và Picasso là cách áp dụng của mình, bạn nên đối chiếu thêm với nguồn khác.</li><li><strong>[Bổ sung]</strong> Điểm 4 ở mục 7 (phase và sect không cùng chiều) mình chưa kiểm chứng trong sách.</li><li>Hình 3 chỉ là sơ đồ minh họa, số giờ trên hình (4h, 6h, 8h, 16h, 18h, 20h) là giá trị giả định.</li><li>Note <code>note_7</code> trước đây ghi &quot;morning = phe ngày&quot; như một quy ước của mình. Đoạn Paulus này xác nhận quy ước đó, nên có thể sửa note cũ cho khớp.</li></ul>',54)])])}const y=t(g,[["render",s]]);export{v as __pageData,y as default};
